import{c as t,Q as a,j as r,m as n}from"./chunks/framework.g_l1frA7.js";const g=JSON.parse('{"title":"Transactions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/transactions.md","filePath":"guide/transactions.md","lastUpdated":null}'),i={name:"guide/transactions.md"};function s(o,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="transactions" tabindex="-1">Transactions <a class="header-anchor" href="#transactions" aria-label="Permalink to &quot;Transactions&quot;">​</a></h1><p>The ledger. Every screen ultimately reads from here — Today, Budget, Reports, and the Copilot all compute from the same rows.</p><h2 id="finding-transactions" tabindex="-1">Finding transactions <a class="header-anchor" href="#finding-transactions" aria-label="Permalink to &quot;Finding transactions&quot;">​</a></h2><ul><li><strong>Search</strong> — merchant substring, amount, or note. Merchant is normalized (<code>finsight-core::merchant</code>) so “SQ *BLUE BOTTLE” and “blue bottle” group together.</li><li><strong>Filters</strong> — date range, account, category, transfer/split, and review state. Saved filters live in the TransactionFilter drawer.</li><li><strong>Review queues</strong> — uncategorized, needs-review, possible transfers, and possible splits are prefiltered for you. See <a href="/FinSight/guide/insights">Insights</a>.</li></ul><h2 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h2><p>Open any row → the <strong>Transaction drawer</strong>:</p><ul><li>Change date, amount, merchant, category, account, or notes.</li><li><strong>Transfers</strong> — link two transactions (e.g. checking → savings) into a single transfer. The double-entry is stored as a pair with a shared identity; either side can be edited and both update.</li><li><strong>Splits</strong> — break one purchase (e.g. groceries + household) into categorized children. The parent amount must equal the sum of children; the drawer enforces this.</li><li><strong>Unconverted currencies</strong> — a banner appears when a transaction’s account currency differs and no rate exists; the amount is kept faithfully, not converted.</li></ul><h2 id="transfers-vs-duplicates" tabindex="-1">Transfers vs duplicates <a class="header-anchor" href="#transfers-vs-duplicates" aria-label="Permalink to &quot;Transfers vs duplicates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Do</th></tr></thead><tbody><tr><td>Same amount leaving account A and arriving in B on the same day</td><td>Link as transfer</td></tr><tr><td>Two identical CSV rows from re-import</td><td>Dedup guard skips it</td></tr><tr><td>Same payee, different amounts, consecutive days</td><td>Leave as two transactions</td></tr></tbody></table><h2 id="merchant-categories" tabindex="-1">Merchant &amp; categories <a class="header-anchor" href="#merchant-categories" aria-label="Permalink to &quot;Merchant &amp; categories&quot;">​</a></h2><p>Merchant raw text is kept, a cleaned <code>merchant_key</code> is indexed, and a centroid embedding may be stored for semantic categorization. See <a href="/FinSight/automation/categorization">Categorization</a>.</p><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><p>The transaction list is virtualized and query-cached (tanstack-query + seven-day IndexedDB persist). Filters that touch merchant text use indexed lookups.</p><p>See also: <a href="/FinSight/guide/categories">Categories</a>, <a href="/FinSight/automation/rules">Rules</a>.</p>',14)])])}const p=t(i,[["render",s]]);export{g as __pageData,p as default};
